	melony: { line: "그래, 우리의 배틀 방식은 매우 혹독하단다!", ace: "단 한 조각뿐이라도 얼음은 얼음! 잘 봐두라고!", lose: "너… 꽤 하는구나? 내 포켓몬이 진 건 물론 분하지만.", win: "얼려서 도망가지 못하게 한다고 했지? 꽁꽁 얼었구나.", src: "mixed" },
